package com.meridiantrust.sentinel.api;
import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.Instant;
public final class Dto { private Dto(){} public record CustomerIn(@NotBlank String externalId,@NotBlank String fullName,String kycRisk,@NotBlank String country){} public record AccountIn(@NotBlank String accountNumber,@NotBlank String customerExternalId,String type,String currency,String riskRating){} public record TxIn(@NotBlank String externalId,@NotBlank String accountNumber,@NotNull BigDecimal amount,@NotBlank String currency,@NotBlank String direction,String counterparty,@NotBlank String jurisdiction,String channel,@NotNull Instant timestamp){} public record DispositionIn(@NotBlank String status,@NotBlank String reason){} public record RuleIn(boolean enabled,@NotNull BigDecimal threshold,@Min(1) int windowHours,@Min(0) int score){} }
